query GetDependencyChain($nodeId: ID!, $direction: RelationDirection = OUTGOING, $maxDepth: Int = 5, $relationTypeIds: [ID!]) {
  getDependencyChain(
    input: {
      nodeId: $nodeId
      direction: $direction
      maxDepth: $maxDepth
      relationTypeIds: $relationTypeIds
    }
  ) {
    nodes {
      id
      content
      table {
        id
        identifier
      }
      attributeCount
      relationCount
    }
    relations {
      id
      relationType {
        identifier
        name
        description
      }
      sourceNode {
        id
        content
      }
      targetNode {
        id
        content
      }
    }
    totalCount
    hasNextPage
    hasPreviousPage
  }
}
